#!/usr/bin/env node
/*
 * Runs every row of vectors.json — generated by the Swift package, see
 * scripts/export-vectors.sh — through vialmath.js and compares.
 *
 *   node site/mix/test.js [path/to/vectors.json]
 *
 * Numbers must agree to 1e-9. Strings, integers and enum kinds must agree
 * exactly. The first mismatch in each section is printed in full; the exit
 * code is the number of failing sections.
 */
const fs = require("fs");
const path = require("path");
const V = require("./vialmath.js");

const file = process.argv[2] || path.join(__dirname, "vectors.json");
const vectors = JSON.parse(fs.readFileSync(file, "utf8"));

const TOL = 1e-9;
function near(a, b) { return Math.abs(a - b) < TOL; }
function cap(ml) { return V.SyringeCapacity.common.find((c) => c.millilitres === ml); }
function input(row) {
  return {
    vialMass: V.mass(row.vial, row.vialUnit),
    diluent: V.volume(row.diluent),
    dose: V.mass(row.dose, row.doseUnit),
    scale: row.scale,
    capacity: cap(row.capacity),
    displayUnit: row.vialUnit,
  };
}

const failures = {};
function fail(section, row, why) {
  failures[section] = failures[section] || [];
  failures[section].push({ row, why });
}

// Forward solve, errors, and the shown working.
for (const row of vectors.forward) {
  let r = null, err = null;
  try { r = V.solve(input(row)); } catch (e) { err = e.code || "unknown"; }
  if (!row.ok) {
    if (err !== row.error) fail("forward", row, "expected error " + row.error + ", got " + (err || "a result"));
    continue;
  }
  if (err) { fail("forward", row, "unexpected error " + err); continue; }
  if (!near(r.concentration.microgramsPerMillilitre, row.concentrationMcgPerMl)) fail("forward", row, "concentration " + r.concentration.microgramsPerMillilitre);
  if (!near(r.doseVolume.millilitres, row.doseVolumeMl)) fail("forward", row, "doseVolume " + r.doseVolume.millilitres);
  if (!near(r.doseUnits, row.doseUnits)) fail("forward", row, "doseUnits " + r.doseUnits);
  if (r.dosesPerVial !== row.dosesPerVial) fail("forward", row, "dosesPerVial " + r.dosesPerVial);
  if (r.readability.kind !== row.readability.kind || !near(r.readability.value, row.readability.value)) fail("forward", row, "readability " + JSON.stringify(r.readability));
  for (let i = 0; i < 4; i++) {
    const a = r.steps[i], b = row.steps[i];
    if (a.id !== b.id || a.label !== b.label || a.expression !== b.expression) {
      fail("steps", row, "step " + i + "\n   js:    " + a.expression + "\n   swift: " + b.expression);
    }
  }
}

// Readability options, bounded by vial capacity.
for (const row of vectors.options) {
  const inp = input(row);
  let r;
  try { r = V.solve(inp); } catch (e) { fail("options", row, "solve threw"); continue; }
  const got = V.readabilityOptions(inp, r, V.volume(row.vialCapacity));
  const want = row.options;
  if (got.length !== want.length) { fail("options", row, "count " + got.length + " vs " + want.length); continue; }
  for (let i = 0; i < got.length; i++) {
    const g = got[i], w = want[i];
    if (g.kind !== w.kind) { fail("options", row, "kind " + g.kind + " vs " + w.kind); break; }
    if (g.kind === "moreDiluent" && (!near(g.volume.millilitres, w.volume) || !near(g.resultingUnits, w.units))) fail("options", row, "moreDiluent " + g.volume.millilitres);
    if (g.kind === "differentBarrel" && !near(g.capacity.millilitres, w.capacity)) fail("options", row, "barrel " + g.capacity.millilitres);
  }
}

// The inverted solve: dose in, water out.
for (const row of vectors.plans) {
  const p = V.dilutionPlan(V.mass(row.vial, row.vialUnit), V.mass(row.dose, row.doseUnit), row.scale, cap(row.barrel), V.volume(row.vialCapacity));
  if (row.plan === null) { if (p !== null) fail("plans", row, "expected null"); }
  else if (p === null) fail("plans", row, "got null");
  else {
    const w = row.plan;
    if (!near(p.diluent.millilitres, w.diluent)) fail("plans", row, "diluent " + p.diluent.millilitres + " vs " + w.diluent);
    else if (!near(p.units, w.units)) fail("plans", row, "units " + p.units + " vs " + w.units);
    else if (p.doses !== w.doses) fail("plans", row, "doses " + p.doses);
    else if (p.limit !== w.limit) fail("plans", row, "limit " + p.limit + " vs " + w.limit);
    else if (!near(p.barrelUse, w.barrelUse)) fail("plans", row, "barrelUse " + p.barrelUse);
    else if (p.isReadable !== w.isReadable || p.isComfortable !== w.isComfortable) fail("plans", row, "flags");
  }
  const e = V.easiestBarrel(7.5, row.scale, cap(row.barrel));
  const want = row.easiestFor7_5;
  if ((e === null) !== (want === null) || (e && !near(e.millilitres, want))) fail("easiest", row, "easiestBarrel " + (e && e.millilitres) + " vs " + want);
}

// Inverse solve.
for (const row of vectors.inverse) {
  const v = V.diluentToPlace(V.mass(row.dose, row.doseUnit), row.target, V.mass(row.vial, row.vialUnit), row.scale);
  if (!near(v.millilitres, row.diluent)) fail("inverse", row, "diluent " + v.millilitres + " vs " + row.diluent);
}

// Readability bands and the better-barrel suggestion.
for (const row of vectors.readability) {
  const r = V.readability(row.units, cap(row.capacity), row.scale);
  if (r.kind !== row.readability.kind || !near(r.value, row.readability.value)) fail("readability", row, JSON.stringify(r));
  const b = V.betterCapacity(row.units, row.scale, cap(row.capacity));
  if ((b === null) !== (row.better === null) || (b && !near(b.millilitres, row.better))) fail("better", row, "better " + (b && b.millilitres) + " vs " + row.better);
}

const counts = {
  forward: vectors.forward.length, steps: vectors.forward.length, options: vectors.options.length,
  plans: vectors.plans.length, easiest: vectors.plans.length, inverse: vectors.inverse.length,
  readability: vectors.readability.length, better: vectors.readability.length,
};
let bad = 0;
for (const section of Object.keys(counts)) {
  const f = failures[section] || [];
  if (f.length) {
    bad++;
    console.log("✗ " + section + ": " + f.length + " of " + counts[section] + " differ. First:");
    console.log("   " + JSON.stringify(f[0].row).slice(0, 300));
    console.log("   " + f[0].why);
  } else {
    console.log("✔ " + section + ": " + counts[section] + " rows agree with the Swift package");
  }
}
process.exit(bad);
